function jumpSearch(hit: SearchHit) {
  if (hit.kind === "person" && hit.person) {
    state.person = hit.person;
    state.inspect = "person";
    state.highlightGame = undefined;
    state.highlightQuery = undefined;
    render();
    return;
  }
  state.inspect = "schedule";
  state.sheetWeek = "all";
  if (hit.kind === "field" || hit.kind === "campus" || hit.kind === "date") state.sheetBracket = "all";
  else if (hit.bracket) state.sheetBracket = hit.bracket;
  state.highlightGame = hit.gameId;
  state.highlightQuery = hit.kind === "game" ? hit.label : hit.kind === "date" ? hit.dateIso : hit.label;
  render();
}

function applySheetAction(action: SheetAction) {
  const league = state.league;
  const cfg = selectedCfg();
  if (!league || !cfg) return;
  const before = scoreSnap(league, cfg);
  let line = "";
  if (action.type === "swap") {
    const { pulled, target } = action;
    line = `Swapped <strong>${publishedClubName(league, pulled.home)}</strong> ${formatSheetDate(pulled.dateIso)} ${formatSheetTime(pulled.kickoff)} ${publishedLocation(league, pulled.campus)} with <strong>${publishedClubName(league, target.home)}</strong> ${formatSheetDate(target.dateIso)} ${formatSheetTime(target.kickoff)} ${publishedLocation(league, target.campus)}.`;
    swapGameSlots(pulled, target);
    state.swapUndo = { kind: "swap", a: pulled.id, b: target.id };
  } else if (action.type === "time") {
    const snap = snapshotSlot(action.game);
    const from = `${formatSheetTime(action.game.kickoff)} ${formatSheetDate(action.game.dateIso)}`;
    applyKickoff(league, action.game, action.kickoff, action.dateIso);
    line = `Moved <strong>${publishedClubName(league, action.game.home)}</strong> from ${from} to ${formatSheetTime(action.game.kickoff)}${action.dateIso ? ` ${formatSheetDate(action.game.dateIso)}` : ""}.`;
    state.swapUndo = { kind: "slot", id: action.game.id, before: snap };
  } else {
    const snap = snapshotSlot(action.game);
    const from = sheetLocation(league, action.game.campus, action.game.field);
    applyField(league, action.game, action.field);
    line = `Moved <strong>${publishedClubName(league, action.game.home)}</strong> from ${from} to ${sheetLocation(league, action.game.campus, action.game.field)}.`;
    state.swapUndo = { kind: "slot", id: action.game.id, before: snap };
  }
  restamp(cfg);
  const after = scoreSnap(league, cfg);
  const r = ramificationCopy(line, before, after);
  state.ramification = r.html;
  state.ramificationKind = r.kind;
  render();
}

function selectedCfg(): Configuration | undefined {
  return state.configurations.find((c) => c.id === state.selectedId) || state.configurations[0];
}

function ensureCfg(): Configuration | undefined {
  const existing = selectedCfg();
  if (existing) return existing;
  if (!state.league) return undefined;
  const cfg: Configuration = {
    id: "cfg-1",
    name: "Configuration 1 — First pass — no carve-outs",
    createdAt: "just now",
    games: [],
    scores: [],
    hardHeld: true,
    diagnostics: [],
    engine: "z3",
    z3Verdict: "sat",
    z3Probe: "sat",
  };
  state.configurations = [cfg];
  state.selectedId = cfg.id;
  return cfg;
}

