$('[data-action="calculate"]').addEventListener("click", async () => {
  if (!state.league) return;
  const league = state.league;
  livePinned = undefined;
  liveHover = undefined;
  liveProgress = undefined;
  const stopVeil = startThinkingVeil(league);
  try {
    const n = state.configurations.length + 1;
    const name =
      n === 1 && !league.carveOuts.length
        ? "Configuration 1 — First pass — no carve-outs"
        : `Configuration ${n} — just now`;
    const prev = selectedCfg();
    const z3Promise = solveInBrowser(league, name);
    const result = await runSeasonGa(league, {
      z3: z3Promise,
      onProgress: (p) => {
        liveProgress = p;
        paintGaVeil(league, p);
      },
    });
    if (result.z3Error) throw result.z3Error;
    const cfg = result.z3Config;
    if (!cfg || cfg.engine !== "z3" || cfg.z3Probe !== "sat") {
      throw new Error("Calculate did not run real Z3 — refusing to keep a placer result");
    }
    if (prev?.games.length) cfg.scores.push(...carveDisplacement(league, prev.games, cfg.games));
    cfg.id = `cfg-${n}`;
    const z3Meta = {
      engine: cfg.engine,
      z3Probe: cfg.z3Probe,
      z3Verdict: cfg.z3Verdict,
      folding: cfg.folding,
      diagnostics: cfg.diagnostics,
      scores: cfg.scores,
      hardHeld: cfg.hardHeld,
    };
    const plan: { genome: Genome; cfg: Configuration }[] = [];
    for (const g of result.top) {
      if (g.origin === "z3") plan.push({ genome: g, cfg });
      else {
        plan.push({
          genome: g,
          cfg: genomeToConfiguration(
            league,
            g,
            `Proposal ${plan.length + 1} — Sims ${g.simsScore}`,
            `cfg-ga-${n}-${plan.length}`,
            z3Meta,
          ),
        });
      }
    }
    if (!plan.some((p) => p.cfg.id === cfg.id)) {
      const zg = result.top.find((g) => g.origin === "z3");
      plan.push({ genome: zg || result.best, cfg });
    }
    const picked = plan.slice(0, 5);
    while (picked.length < 5 && result.best) {
      const g = result.top[picked.length] || result.best;
      picked.push({
        genome: g,
        cfg: genomeToConfiguration(league, g, `Proposal ${picked.length + 1} — Sims ${g.simsScore}`, `cfg-ga-${n}-x${picked.length}`, z3Meta),
      });
    }
    state.planTop = picked.map((p) => p.genome);
    state.proposals = picked.map((p) => p.cfg);
    state.proposalIndex = 0;
    state.pinnedDay = undefined;
    state.hoverDay = undefined;
    const ids = new Set(state.proposals.map((p) => p.id));
    state.configurations = [...state.proposals, ...state.configurations.filter((c) => !ids.has(c.id))];
    state.selectedId = state.proposals[0]?.id || cfg.id;
    state.constraintKey = constraintKey(league);
    state.refreshLine = undefined;
    state.inspect = "schedule";
    state.ownScars = false;
    stopVeil();
    liveProgress = undefined;
    render();
  } catch (err) {
    stopVeil();
    liveProgress = undefined;
    const msg = err instanceof Error ? err.message : String(err);
    showRefusal(msg);
  }
});

