$('[data-panel="inspect-cards"]').addEventListener("click", async (e) => {
  const target = (e.target as HTMLElement).closest("[data-doc], [data-action], [data-cast]") as HTMLElement | null;
  if (!target) return;
  if (!state.league) return;
  if (target.getAttribute("data-action") === "undo-swap") {
    const cfg = selectedCfg();
    const ids = state.swapUndo;
    if (!cfg || !state.league || !ids) return;
    const before = scoreSnap(state.league, cfg);
    if (ids.kind === "slot") {
      const g = cfg.games.find((x) => x.id === ids.id);
      if (!g) return;
      const now = snapshotSlot(g);
      restoreSlot(g, ids.before);
      state.swapUndo = { kind: "slot", id: g.id, before: now };
    } else {
      const ga = cfg.games.find((g) => g.id === ids.a);
      const gb = cfg.games.find((g) => g.id === ids.b);
      if (!ga || !gb) return;
      swapGameSlots(ga, gb);
      state.swapUndo = { kind: "swap", a: ids.b, b: ids.a };
    }
    restamp(cfg);
    const after = scoreSnap(state.league, cfg);
    const r = ramificationCopy("Undid the last swap.", before, after);
    state.ramification = r.html;
    state.ramificationKind = r.kind;
    render();
    return;
  }
  if (target.getAttribute("data-action") === "wash-out") {
    const week = target.getAttribute("data-week") || "";
    const blocked = week && state.league ? canWashDate(state.league, week) : "No date.";
    if (blocked) {
      state.washNote = blocked;
      render();
      return;
    }
    state.washFrom = week;
    state.washNote = undefined;
    render();
    return;
  }
  if (target.getAttribute("data-action") === "rain-choice") {
    const toIso = target.getAttribute("data-rain-choice") || "";
    const fromIso = state.washFrom;
    const src = selectedCfg();
    if (!state.league || !src || !fromIso || !toIso) return;
    const veil = $('[data-veil="thinking"]');
    const fromLine = $('[data-veil-line="grid"]');
    if (fromLine) fromLine.textContent = `moving ${shortMonthDay(fromIso)} onto the rain-check grid…`;
    const people = $('[data-veil-line="people"]');
    if (people) people.textContent = "keeping owed games at twelve — this is not a new Saturday…";
    veil.setAttribute("data-veil-engine", "z3");
    show(veil, true);
    await new Promise((r) => setTimeout(r, 60));
    const copy = structuredClone(src);
    const result = applyWashout(state.league, copy.games, fromIso, toIso);
    if (!result.moved || !result.washout) {
      show(veil, false);
      state.washNote = result.diagnostics[0] || "Nothing could move.";
      src.diagnostics = [...new Set([...(src.diagnostics || []), ...result.diagnostics])];
      render();
      return;
    }
    const n = state.configurations.length + 1;
    copy.id = `cfg-${n}`;
    copy.name = `${shortMonthDay(fromIso)} → ${shortMonthDay(toIso)}`;
    copy.createdAt = "just now";
    copy.published = false;
    copy.games = result.games;
    copy.washouts = [...(src.washouts || []), result.washout];
    copy.diagnostics = result.diagnostics;
    restamp(copy);
    copy.scores.push({
      key: "rain-check",
      text: `moved ${shortMonthDay(fromIso)} onto ${shortMonthDay(toIso)} — still ${owedGames(state.league)} games owed`,
    });
    const shared = copy.scores.find((s) => s.key === "shared-coach");
    if (shared && !copy.diagnostics.some((d) => /camel's back/i.test(d))) {
      copy.scores.push({
        key: "rain-coach",
        text: shared.text.replace("kept apart", "kept apart on rain check"),
      });
    }
    state.configurations = [copy, ...state.configurations];
    state.selectedId = copy.id;
    state.washFrom = undefined;
    state.washNote = undefined;
    state.inspect = "schedule";
    show(veil, false);
    render();
    return;
  }
  if (target.getAttribute("data-action") === "publish-config") {
    const cfg = selectedCfg();
    if (!cfg || !state.league) return;
    for (const c of state.configurations) c.published = c.id === cfg.id;
    state.publishedId = cfg.id;
    render();
    return;
  }
  const kind = target.getAttribute("data-doc");
  const cfg = selectedCfg();
  if (!cfg) return;
  const xlsx = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
  if (kind === "league-schedule") {
    const wb = await leagueScheduleWorkbook(state.league, cfg);
    downloadBlob("VSA-Fall-2026-Schedule.xlsx", await workbookToBuffer(wb), xlsx);
  } else if (kind === "academy-schedule") {
    const wb = await leagueScheduleWorkbook(state.league, cfg, { onlyAssociation: "Van Academy" });
    downloadBlob("VSA-Fall-2026-Academy.xlsx", await workbookToBuffer(wb), xlsx);
  } else if (kind === "family-schedules") {
    const scars = documentScars(state.league, cfg);
    if (documentsHeld(scars) && !state.ownScars) return;
    const zip = await familyZip(state.league, cfg);
    downloadBlob("VSA-Fall-2026-Families.zip", zip, "application/zip");
  } else if (kind === "player-schedules") {
    const zip = await playerZip(state.league, cfg);
    downloadBlob("VSA-Fall-2026-Players.zip", zip, "application/zip");
  } else if (kind === "referee-assignments") {
    const wb = await refereeWorkbook(state.league, cfg);
    downloadBlob("VSA-Fall-2026-Referees.xlsx", await workbookToBuffer(wb), xlsx);
  }
});

$('[data-panel="inspect-cards"]').addEventListener("change", (e) => {
  const box = (e.target as HTMLElement).closest('[data-field="own-scars"]') as HTMLInputElement | null;
  if (box) {
    state.ownScars = box.checked;
    render();
    return;
  }
  const jack = (e.target as HTMLElement).closest("[data-jack]") as HTMLSelectElement | null;
  if (!jack || !state.league) return;
  const cfg = selectedCfg();
  if (!cfg) return;
  const id = jack.getAttribute("data-game-id");
  const game = cfg.games.find((g) => g.id === id);
  if (!game) return;
  const kind = jack.getAttribute("data-jack");
  if (kind === "opponent") {
    game.away = jack.value;
  } else if (kind === "kickoff") {
    const kick = parseClock(jack.value);
    if (kick != null) {
      const len = Math.max(40, (parseClock(game.end) || kick + 50) - (parseClock(game.kickoff) || kick));
      game.kickoff = jack.value;
      game.warmupStart = formatClockShort(kick - 15);
      game.end = formatClockShort(kick + len);
      game.vacate = formatClockShort(kick + len + 10);
    }
  }
  restamp(cfg);
  render();
});

async function importWorkbook(file: File) {
  const ribbon = $('[data-progress="import"]');
  ribbon.textContent = "Reading sheets…";
  show(ribbon, true);
  await new Promise((r) => setTimeout(r, 40));
  ribbon.textContent = "Building the season file…";
  const buf = await file.arrayBuffer();
  const result = await parseWorkbook(buf, file.name);
  show(ribbon, false);
  const bench = $('[data-screen="workbench"]');
  if (result.strategy) bench.setAttribute("data-intake-strategy", result.strategy);
  else bench.removeAttribute("data-intake-strategy");
  const missing = result.issues.filter((i) => i.level === "flag" && i.code.startsWith("missing-"));
  bench.setAttribute("data-intake-partial", missing.length ? "yes" : "no");
  if (!result.ok) {
    showRefusal(result.issues.map((i) => i.message).join("\n"));
    render();
    return;
  }
  hideRefusal();
  const next = result.league!;
  if (result.issues.some((i) => i.code === "unreadable-date")) {
    next.season.dateFlags = result.issues
      .filter((i) => i.code === "unreadable-date")
      .map((i) => ({ raw: i.message, message: i.message }));
  }
  if (state.configurations.length && state.constraintKey) {
    const reason = staleReason(state.constraintKey, next);
    if (!reason) {
      state.refreshLine = "Workbook refreshed — phones and spellings updated; placements kept.";
      for (const c of state.configurations) {
        stampSeasonScores(next, c);
        applySimsJudgment(next, c);
      }
    } else {
      const names = state.configurations.map((c) => c.name.replace(/ —.*/, "")).join(" and ");
      state.refreshLine = `${names} were solved before this refusal. Recalculate.`;
      for (const c of state.configurations) {
        c.stale = `STALE — ${reason}`;
        c.published = false;
      }
      state.publishedId = undefined;
    }
  } else {
    state.configurations = [];
    state.selectedId = undefined;
    state.refreshLine = undefined;
  }
  state.league = next;
  state.constraintKey = constraintKey(next);
  render();
}

function showRefusal(body: string) {
  const card = $('[data-refusal="import"]');
  const title = $("[data-refusal-title]");
  const p = $("[data-refusal-body]");
  if (/not the Van Season workbook/i.test(body) && !/Age groups/i.test(body)) {
    title.textContent = "This is not the Van Season workbook. Download the sample and copy your data into those colored sheets.";
    p.textContent = body;
  } else if (/missing shapes|Age groups, Fields/i.test(body)) {
    title.textContent = "This is not the Van Season workbook.";
    p.textContent = "Age groups, Fields, Campuses, Associations, Families, Staff, Teams, Season";
  } else if (/Z3|SharedArrayBuffer|cross-origin isolated|initZ3/i.test(body)) {
    title.textContent = "Z3 could not calculate this season.";
    p.textContent = body;
    p.setAttribute("data-z3-error", "true");
  } else {
    title.textContent = "The workbook could not become a season.";
    p.textContent = body;
  }
  show(card, true);
}

