function pickTraces(demo: SimsDemo): SimsTrace[] {
  const fail = demo.score.traces.filter((t) => t.verdict !== "makes-it");
  if (fail.length) return fail;
  const families = demo.score.traces.filter((t) => t.kind === "family" && t.verdict === "makes-it");
  const named = families.filter((t) => /Hale|Diaz/i.test(t.subject));
  return (named.length ? named : families).slice(0, 3);
}

function paintProof(host: HTMLElement, demo: SimsDemo) {
  const score = demo.score;
  const traces = pickTraces(demo);
  host.setAttribute("data-sims-feasible", score.feasible ? "yes" : "no");
  host.setAttribute("data-sims-valid", score.legal ? "yes" : "no");
  host.setAttribute("data-sims-score", String(score.score));
  const legalLine = score.legal ? "the grid is legal" : "the grid is not legal";
  host.innerHTML = `
    <h3>Saturday proof — ${formatLong(demo.dateIso)}</h3>
    <p class="meta">Every car, every whistle, every kid. The best plan is the verdict — not the solver's word alone.</p>
    <div class="demo-score ${score.feasible ? "ok" : "rust"}" data-sims-banner="${score.feasible ? "holds" : "fails"}">
      <p data-sims-verdict>${score.feasible ? "Saturday holds" : "This Saturday does not hold"} · score ${score.score}</p>
      <p class="meta" data-sims-counts data-sims-legal="${score.legal ? "yes" : "no"}">${legalLine} · two places ${score.twoPlaces} · referee flights ${score.refFlights} · cars short ${score.carsShort}</p>
      ${score.scars.map((s) => `<p class="flag" data-scar="${s.kind}">${s.text}</p>`).join("")}
    </div>
    <div class="proof-traces" data-sims-traces>
      ${traces
        .map(
          (t) => `<article class="proof-trace" data-trace="${t.id}" data-trace-verdict="${t.verdict}" data-trace-subject="${t.subject}">
        <p data-trace-headline>${t.headline}</p>
        <ol data-trace-steps>${t.steps.map((s) => `<li data-trace-step>${s}</li>`).join("")}</ol>
      </article>`,
        )
        .join("")}
    </div>
  `;
}

