function paintGaVeil(league: League, p: GaProgress) {
  const gen = $("[data-ga-generation]");
  const sims = $("[data-ga-best-sims]");
  const joined = $("[data-ga-z3-joined]");
  if (gen) gen.textContent = `generation ${p.generation}`;
  if (sims) sims.textContent = `best Sims ${p.bestSims}`;
  if (joined) {
    joined.setAttribute("data-ga-z3-joined", p.z3Joined ? "yes" : "no");
    joined.textContent = p.z3Joined ? "Z3 sitting in the pool" : "Z3 sitting not in yet";
  }
  const map = $("[data-ga-minimap]");
  if (map && p.best) {
    map.innerHTML = minimapHtml(p.best.days, { live: true, pinned: livePinned, hover: liveHover });
  }
  const entry = $("[data-ga-day-entry]");
  if (entry && p.best) {
    const iso = livePinned || liveHover;
    const cell = p.best.days.find((d) => d.dateIso === iso);
    entry.innerHTML = dayEntryHtml(league, cell, !!livePinned && livePinned === iso);
  }
}

function startThinkingVeil(league: League): () => void {
  const veil = $('[data-veil="thinking"]');
  const grid = $('[data-veil-line="grid"]');
  const people = $('[data-veil-line="people"]');
  const cramp = $('[data-veil-line="cramp"]');
  const scratcher = isScratcherLeague(league);
  veil.setAttribute("data-veil-engine", "z3");
  veil.setAttribute("data-veil-corpus", scratcher ? "scratcher" : "sample");
  const beats = scratcher
    ? [
        ["packing 300 kids onto eight pitches…", "eight referees, one 10U field — every Saturday counts…", "16U has no local opponent; guests must travel…"],
        ["placing games on the 15-minute grid…", "keeping parent-coaches in one place at a time…", "Mineola, Forney, Lindale take the 16U Saturdays…"],
        ["warm-up and vacate on the same grass…", "one car, two brackets, one campus when we can…", "Z3 is packing the whole fall, not a single week…"],
      ]
    : [
        ["placing games on the 15-minute grid…", "keeping coaches and parents in one place at a time…", ""],
        ["preferred 6U slots first, then 8U…", "folding easy sides so the SAT heap stays small…", ""],
      ];
  let i = 0;
  const paint = () => {
    const b = beats[i % beats.length];
    if (grid) grid.textContent = b[0];
    if (people) people.textContent = b[1];
    if (cramp) {
      cramp.textContent = b[2] || "";
      cramp.hidden = !b[2];
    }
    i += 1;
  };
  paint();
  const gen = $("[data-ga-generation]");
  const sims = $("[data-ga-best-sims]");
  const joined = $("[data-ga-z3-joined]");
  if (gen) gen.textContent = "generation 0";
  if (sims) sims.textContent = "best Sims —";
  if (joined) {
    joined.setAttribute("data-ga-z3-joined", "no");
    joined.textContent = "Z3 sitting not in yet";
  }
  const map = $("[data-ga-minimap]");
  if (map) map.innerHTML = minimapHtml(scoreCheap(league, []).days, { live: true });
  show(veil, true);
  const t = window.setInterval(paint, 2200);
  return () => {
    window.clearInterval(t);
    show(veil, false);
    if (grid) grid.textContent = VEIL_DEFAULT.grid;
    if (people) people.textContent = VEIL_DEFAULT.people;
    if (cramp) {
      cramp.textContent = "";
      cramp.hidden = true;
    }
    veil.removeAttribute("data-veil-corpus");
    const map = $("[data-ga-minimap]");
    if (map) map.innerHTML = "";
    const entry = $("[data-ga-day-entry]");
    if (entry) entry.innerHTML = "";
  };
}

