function complexityMapHtml(league: League, cfg?: Configuration): string {
  const plan = foldLeague(league);
  const snap = cfg?.folding || snapshotFolding(plan);
  const units = snap.teams.filter((t) => t.kind === "unit");
  const exploded = snap.teams.filter((t) => t.kind === "exploded");
  const specials = snap.households.filter((h) => h.kind === "exploded");
  const engine = cfg?.engine || "";
  const row = (
    kind: "unit" | "exploded",
    display: string,
    extra: string,
    vars?: number,
    naive?: number,
  ) =>
    `<div class="fold-row" data-fold-row data-fold="${kind}" ${extra}>
      <strong>${display}</strong>
      ${vars != null ? `<span class="meta" data-fold-vars="${vars}" data-fold-naive="${naive ?? ""}">${kind === "unit" ? "1 unit" : vars + " SAT keys"} · ${naive ?? "?"} people</span>` : ""}
    </div>`;
  return `<article class="card complexity-map" data-card="complexity-map" data-engine="${engine}" data-heap-folded="${snap.foldedVars}" data-heap-naive="${snap.naiveVars}" data-heap-bound="${snap.bound}" data-heap-z3="${snap.z3Vars || ""}">
    <h3>Complexity map</h3>
    <p class="meta">Why the SAT heap stayed small. Folded teams travel as one block.</p>
    <p data-heap-line>folded ${snap.foldedVars} · naive ${snap.naiveVars} people · bound ${snap.bound}${snap.z3Vars ? ` · Z3 vars ${snap.z3Vars} / Saturday` : ""}</p>
    <p class="fold-heading">Easy peasy</p>
    ${units.map((t) => row("unit", t.display, `data-team="${t.label}" data-fold-caption="${t.caption}"`, t.varCount, t.naiveCount)).join("") || `<p class="meta">No simple units this season.</p>`}
    <p class="fold-heading">Complexity here and there</p>
    ${specials.map((h) => row("exploded", h.display, `data-household="${h.last}" data-fold-caption="${h.caption}" data-fold-reasons="${h.reasons.join(",")}"`)).join("")}
    ${exploded.map((t) => row("exploded", t.display, `data-team="${t.label}" data-fold-caption="${t.caption}"`, t.varCount, t.naiveCount)).join("")}
  </article>`;
}

function headerText(league: League | null): string {
  if (!league) return "Van Season — Fall 2026";
  if (league.sampleOnly) return "Van Season — Fall 2026";
  const assoc = league.season.associationName || "Van Soccer Association";
  const title = league.season.headerTitle || "Fall 2026";
  if (/van soccer association/i.test(assoc)) return `${assoc} — Fall 2026`;
  return `${assoc} — ${title}`;
}

function render() {
  const league = state.league;
  $('[data-header="product"]').textContent = headerText(league);
  const pubLine = $("[data-published-line]");
  if (pubLine) {
    const pub = state.configurations.find((c) => c.id === state.publishedId && c.published);
    pubLine.textContent = pub ? `Published: ${pub.name}` : "Published: none yet";
    pubLine.hidden = !league || !state.configurations.length;
  }
  show($('[data-banner="empty"]'), !league);
  show($('[data-action="download-workbook"]'), !!league);
  show($('[data-action="save-season"]'), !!league);
  show($('[data-action="calculate"]'), !!league);
  show($('[data-panel="inspect"]'), !!league);
  $('[data-screen="workbench"]').classList.toggle("has-league", !!league);
  $('[data-screen="workbench"]').classList.toggle("sheet-mode", state.inspect === "schedule" && !!selectedCfg()?.games.length);
  const q = ($('[data-field="search"]') as HTMLInputElement).value.trim();
  const searchEmpty = $('[data-banner="search-empty"]');
  if (q && /practice/i.test(q)) {
    searchEmpty.textContent = "Nothing in Season, Goals, or Calculate offers a practice week. Games only this season.";
    show(searchEmpty, true);
  } else {
    show(searchEmpty, false);
  }

  if (league) {
    const flags = inspectFlags(league);
    const noField = flags.find((f) => f.code === "no-legal-field" && /14u/i.test(f.message));
    const calc = $('[data-action="calculate"]');
    if (noField) calc.textContent = "Calculate (14U has no legal field)";
    else {
      const short = flags.find((f) => f.code === "roster-short" || f.code === "team-floor");
      const loc = flags.find((f) => f.code === "campus-no-location");
      if (short) {
        const who = short.message.split(":")[0].trim();
        const need = short.message.match(/asked for (\d+)|needs (\d+)/);
        const n = need?.[1] || need?.[2] || "3";
        calc.textContent = `Calculate (${who} cannot field ${n})`;
      } else if (loc) calc.textContent = "Calculate (Canton Fields has no location)";
      else calc.textContent = "Calculate game schedule";
    }
    renderInspect(league);
  }
}

