/** Constraint digest so a phone fix keeps Saturdays and a new refusal does not. */

import { teamLabel, type League } from "./model";

export function constraintKey(league: League): string {
  const rows = league.teams.map(
    (t) =>
      `${teamLabel(t)}|play:${[...t.willNotPlay].map((s) => s.trim()).filter(Boolean).sort().join(",")}|travel:${[...t.willNotTravelTo].map((s) => s.trim()).filter(Boolean).sort().join(",")}`,
  );
  const carve = league.carveOuts
    .map((c) => [c.team, c.date || "", c.notAt || "", c.mustUse || "", c.everySaturday ? "1" : "0"].join("/"))
    .sort()
    .join(";");
  return [...rows, `rematch:${league.season.rematchCap}`, `carve:${carve}`].sort().join("\n");
}

export function staleReason(prevKey: string, league: League): string | undefined {
  const next = constraintKey(league);
  if (prevKey === next) return undefined;
  for (const t of league.teams) {
    const label = teamLabel(t);
    const prevLine = prevKey.split("\n").find((l) => l.startsWith(`${label}|`));
    if (!prevLine) continue;
    const prevPlay = (prevLine.split("|")[1] || "").replace(/^play:/, "");
    const nowPlay = [...t.willNotPlay].map((s) => s.trim()).filter(Boolean).sort().join(",");
    if (nowPlay === prevPlay) continue;
    const extra = nowPlay.split(",").filter((x) => x && !prevPlay.split(",").includes(x));
    if (extra[0]) return `solved before ${label} refused ${extra[0]}`;
  }
  return "solved before a constraint changed";
}
