/** Whole-season sheet: DATE TIME HOME AWAY LOCATION, pointer-drag to time and field. */

import { formatClockShort, formatSheetDate, formatSheetTime, parseClock } from "./dates";
import { norm, teamLabel, type Configuration, type League, type PlacedGame } from "./model";
import { publishedClubName } from "./publish";
import { findField } from "./season-score";
import { seasonBurnLines } from "./sims";
import { campusStreet } from "./validate";

export const SLOT = [
  "dateIso",
  "weekIso",
  "kickoff",
  "end",
  "warmupStart",
  "vacate",
  "field",
  "campus",
  "parking",
] as const;

export type SlotSnap = Pick<PlacedGame, (typeof SLOT)[number]>;

export const BRACKET_ORDER = ["6U", "8U", "10U", "10U Girls", "12U", "14U", "14U Girls", "16U"];

export function snapshotSlot(g: PlacedGame): SlotSnap {
  const o = {} as SlotSnap;
  for (const k of SLOT) o[k] = g[k];
  return o;
}

export function restoreSlot(g: PlacedGame, snap: SlotSnap): void {
  Object.assign(g, snap);
}

export function swapGameSlots(a: PlacedGame, b: PlacedGame): void {
  for (const k of SLOT) {
    const tmp = a[k];
    Object.assign(a, { [k]: b[k] });
    Object.assign(b, { [k]: tmp });
  }
}

export interface ScoreSnap {
  z3: number | undefined;
  diversity: number | undefined;
  simsLegal: boolean;
  burns: string[];
}

export function scoreSnap(league: League, cfg: Configuration): ScoreSnap {
  return {
    z3: cfg.z3Season?.score,
    diversity: cfg.diversity?.score,
    simsLegal: cfg.simsValid !== false && !cfg.scores.some((s) => s.key === "sims" && /not legal/i.test(s.text)),
    burns: seasonBurnLines(league, cfg),
  };
}

function deltaWord(before: number | undefined, after: number | undefined, higherIsBetter: boolean): "better" | "worse" | "same" {
  if (before == null || after == null || before === after) return "same";
  const up = after > before;
  return (higherIsBetter ? up : !up) ? "better" : "worse";
}

export function ramificationCopy(
  swapLine: string,
  before: ScoreSnap,
  after: ScoreSnap,
): { html: string; kind: "better" | "worse" | "same" } {
  const z = deltaWord(before.z3, after.z3, true);
  const d = deltaWord(before.diversity, after.diversity, true);
  const s: "better" | "worse" | "same" =
    before.simsLegal === after.simsLegal ? "same" : after.simsLegal ? "better" : "worse";
  const kind = [z, d, s].includes("worse") ? "worse" : [z, d, s].includes("better") ? "better" : "same";
  const newBurns = after.burns.filter((b) => !before.burns.includes(b));
  const html = `<p data-ramification-swap>${swapLine}</p>
    <p data-ramification-z3 data-delta="${z}">Z3 season ${before.z3 ?? "—"} → ${after.z3 ?? "—"} (${z})</p>
    <p data-ramification-diversity data-delta="${d}">Diversity ${before.diversity ?? "—"} → ${after.diversity ?? "—"} (${d})</p>
    <p data-ramification-sims data-delta="${s}">Sims ${before.simsLegal ? "legal" : "not legal"} → ${after.simsLegal ? "legal" : "not legal"} (${s})</p>
    ${newBurns.length ? newBurns.map((b) => `<p class="flag" data-ramification-burn>${b}</p>`).join("") : `<p class="meta" data-ramification-burn="none">No new household or whistle burns.</p>`}`;
  return { html, kind };
}

export function isDateLead(dateIso: string, prevDateIso?: string | null): boolean {
  return !prevDateIso || prevDateIso !== dateIso;
}

export function dropTargetId(pulledId: string | null | undefined, underId: string | null | undefined): string | undefined {
  if (!pulledId || !underId || pulledId === underId) return undefined;
  return underId;
}

export function isAwayCampus(location: string): boolean {
  return !/van/i.test(location || "");
}

/** Terse campus for the sheet — never a street. Packets still print the address. */
export function terseCampus(campus: string): string {
  if (!campus || /^tba$/i.test(campus)) return "TBA";
  if (/van/i.test(campus)) return /stadium|high school/i.test(campus) ? "Van Stadium" : "Van";
  return campus.replace(/\s+Complex$/i, "").replace(/\s+High School.*$/i, "").trim() || "TBA";
}

/** LOCATION column: campus plus grass. Streets live on title / data-street. */
export function sheetLocation(_league: League, campus: string, field: string): string {
  const loc = terseCampus(campus);
  let f = (field || "").replace(/^Field\s+/i, "").trim();
  if (f && loc && f.toLowerCase().startsWith(loc.toLowerCase())) {
    f = f.slice(loc.length).replace(/^[\s·\-]+/, "").trim();
  }
  if (f && /stadium/i.test(loc) && /stadium/i.test(f)) return loc;
  return f ? `${loc} · ${f}` : loc;
}

export function sheetClubName(league: League, label: string, bracket: string): string {
  const full = publishedClubName(league, label);
  if (!bracket || bracket === "all") return full;
  const cut = full.split(bracket).join("").replace(/\s+/g, " ").trim();
  return cut || full;
}

export function kickoffMinutes(raw: string): number {
  const n = parseClock(raw);
  if (n == null) return 24 * 60;
  return n < 7 * 60 ? n + 12 * 60 : n;
}

export function compareSheetGames(
  a: { dateIso: string; kickoff: string; field: string },
  b: { dateIso: string; kickoff: string; field: string },
): number {
  return a.dateIso.localeCompare(b.dateIso) || kickoffMinutes(a.kickoff) - kickoffMinutes(b.kickoff) || a.field.localeCompare(b.field);
}

export function weekForBracket(
  games: PlacedGame[],
  bracket: string,
  requested?: string | null,
): string | undefined {
  const of = bracket === "all" ? games : games.filter((g) => g.ageGroup === bracket);
  if (requested === "all") return undefined;
  if (requested && of.some((g) => g.dateIso === requested)) return requested;
  const dates = [...new Set(of.map((g) => g.dateIso))].sort();
  const first = dates[0];
  if (first && of.filter((g) => g.dateIso === first).length >= 2) return first;
  return undefined;
}

export interface SheetRow {
  id: string;
  dateIso: string;
  date: string;
  time: string;
  kickoff: string;
  home: string;
  away: string;
  location: string;
  street: string;
  bracket: string;
  homeLabel: string;
  awayLabel: string;
  field: string;
  campus: string;
}

export type SheetLine = { kind: "break"; dateIso: string } | { kind: "game"; row: SheetRow };

export function gamesForSheet(games: PlacedGame[], bracket: string, weekIso?: string): PlacedGame[] {
  return games
    .filter((g) => (bracket === "all" || g.ageGroup === bracket) && (!weekIso || g.dateIso === weekIso))
    .sort(compareSheetGames);
}

export function sheetRow(league: League, g: PlacedGame): SheetRow {
  return {
    id: g.id,
    dateIso: g.dateIso,
    date: formatSheetDate(g.dateIso),
    time: formatSheetTime(g.kickoff),
    kickoff: g.kickoff,
    home: sheetClubName(league, g.home, g.ageGroup),
    away: sheetClubName(league, g.away, g.ageGroup),
    location: sheetLocation(league, g.campus, g.field),
    street: campusStreet(league, g.campus) || "",
    bracket: g.ageGroup,
    homeLabel: g.home,
    awayLabel: g.away,
    field: g.field,
    campus: g.campus,
  };
}

export function sheetLines(league: League, games: PlacedGame[], bracket: string, weekIso?: string): SheetLine[] {
  const rows = gamesForSheet(games, bracket, weekIso).map((g) => sheetRow(league, g));
  const out: SheetLine[] = [];
  let prev: string | undefined;
  for (const row of rows) {
    if (prev && prev !== row.dateIso) out.push({ kind: "break", dateIso: row.dateIso });
    out.push({ kind: "game", row });
    prev = row.dateIso;
  }
  return out;
}

export function sheetBrackets(games: PlacedGame[]): string[] {
  return [...new Set(games.map((g) => g.ageGroup))].sort(
    (a, b) =>
      (BRACKET_ORDER.indexOf(a) < 0 ? 99 : BRACKET_ORDER.indexOf(a)) -
        (BRACKET_ORDER.indexOf(b) < 0 ? 99 : BRACKET_ORDER.indexOf(b)) || a.localeCompare(b),
  );
}

export function gameLengthMinutes(league: League, bracket: string): number {
  return league.ageGroups.find((a) => norm(a.name) === norm(bracket))?.gameLengthMinutes || 50;
}

export function occupyFromKickoff(
  kickoff: string,
  lengthMinutes: number,
): Pick<PlacedGame, "end" | "warmupStart" | "vacate"> {
  const kick = parseClock(kickoff) ?? 0;
  const len = lengthMinutes > 0 ? lengthMinutes : 50;
  return {
    warmupStart: formatClockShort(Math.max(0, kick - 15)),
    end: formatClockShort(kick + len),
    vacate: formatClockShort(kick + len + 10),
  };
}

export function applyKickoff(league: League, game: PlacedGame, kickoff: string, dateIso?: string): void {
  game.kickoff = kickoff;
  if (dateIso) {
    game.dateIso = dateIso;
    game.weekIso = dateIso;
  }
  Object.assign(game, occupyFromKickoff(kickoff, gameLengthMinutes(league, game.ageGroup)));
}

export function applyField(league: League, game: PlacedGame, fieldName: string): void {
  const f = findField(league, fieldName);
  game.field = f?.name || fieldName;
  if (f) {
    game.campus = f.campus;
    game.parking = f.parking;
  }
}

export function kickoffChoices(league: League, games: PlacedGame[], bracket: string): string[] {
  const fromGames = gamesForSheet(games, bracket).map((g) => g.kickoff);
  const fromSlots = league.preferredSlots
    .filter((p) => bracket === "all" || norm(p.bracket) === norm(bracket))
    .map((p) => p.time);
  return [...new Set([...fromGames, ...fromSlots].filter(Boolean))].sort((a, b) => kickoffMinutes(a) - kickoffMinutes(b));
}

export function fieldChoices(
  league: League,
  games: PlacedGame[],
  bracket: string,
): { name: string; campus: string; label: string }[] {
  const seen = new Map<string, { name: string; campus: string; label: string }>();
  const add = (name: string, campus: string) => {
    const k = `${norm(name)}|${norm(campus)}`;
    if (!name || seen.has(k)) return;
    seen.set(k, { name, campus, label: sheetLocation(league, campus, name) });
  };
  for (const g of gamesForSheet(games, bracket)) add(g.field, g.campus);
  for (const f of league.fields) add(f.name, f.campus);
  return [...seen.values()];
}

export interface DropHint {
  gameId?: string | null;
  drop?: string | null;
  timeSlot?: string | null;
  fieldSlot?: string | null;
  kickoff?: string | null;
  dateIso?: string | null;
  field?: string | null;
}

export interface DropHit {
  kind: "swap" | "time" | "field";
  targetId?: string;
  kickoff?: string;
  dateIso?: string;
  field?: string;
}

export function resolveDrop(pulledId: string, under: DropHint | null | undefined): DropHit | undefined {
  if (!pulledId || !under) return undefined;
  if (under.timeSlot) return { kind: "time", kickoff: under.timeSlot };
  if (under.fieldSlot) return { kind: "field", field: under.fieldSlot };
  const other = dropTargetId(pulledId, under.gameId);
  if (under.drop === "time" && (under.kickoff || other)) {
    return { kind: "time", targetId: other, kickoff: under.kickoff || undefined, dateIso: under.dateIso || undefined };
  }
  if (under.drop === "field" && (under.field || other)) {
    return { kind: "field", targetId: other, field: under.field || undefined };
  }
  if (other) return { kind: "swap", targetId: other };
  return undefined;
}

export function hintFromElement(el: Element | null): DropHint | undefined {
  if (!el) return undefined;
  const slot = el.closest("[data-time-slot]") as HTMLElement | null;
  if (slot) return { timeSlot: slot.getAttribute("data-time-slot") };
  const field = el.closest("[data-field-slot]") as HTMLElement | null;
  if (field) return { fieldSlot: field.getAttribute("data-field-slot") };
  const cell = el.closest("[data-drop]") as HTMLElement | null;
  const row = el.closest("[data-sheet-row][data-game]") as HTMLElement | null;
  if (cell) {
    return {
      gameId: cell.getAttribute("data-game") || row?.getAttribute("data-game"),
      drop: cell.getAttribute("data-drop"),
      kickoff: cell.getAttribute("data-kickoff") || row?.getAttribute("data-kickoff"),
      dateIso: cell.getAttribute("data-week") || row?.getAttribute("data-week"),
      field: cell.getAttribute("data-field") || row?.getAttribute("data-field"),
    };
  }
  if (row) {
    return {
      gameId: row.getAttribute("data-game"),
      kickoff: row.getAttribute("data-kickoff"),
      dateIso: row.getAttribute("data-week"),
      field: row.getAttribute("data-field"),
    };
  }
  return undefined;
}

export function rowMatchesQuery(row: SheetRow, q?: string, gameId?: string): boolean {
  if (gameId && row.id === gameId) return true;
  const needle = (q || "").trim().toLowerCase();
  if (!needle) return false;
  return [row.home, row.away, row.homeLabel, row.awayLabel, row.location, row.date, row.time, row.bracket, row.field, row.campus, row.dateIso].some(
    (s) => s.toLowerCase().includes(needle),
  );
}

export function diversityMatrixHtml(league: League, cfg: Configuration): string {
  const brackets = sheetBrackets(cfg.games);
  return brackets
    .map((bracket) => {
      const names = league.teams.filter((t) => t.bracket === bracket).map((t) => teamLabel(t));
      const pool = names.length ? names : [...new Set(cfg.games.filter((g) => g.ageGroup === bracket).flatMap((g) => [g.home, g.away]))];
      if (pool.length < 2) return "";
      const counts = new Map<string, number>();
      for (const g of cfg.games) {
        if (g.ageGroup !== bracket) continue;
        const k = [g.home, g.away].sort().join("|");
        counts.set(k, (counts.get(k) || 0) + 1);
      }
      return `<div class="matrix-wrap" data-diversity-matrix="${bracket}">
        <p class="meta">${bracket} who-played-whom</p>
        <table><thead><tr><th></th>${pool.map((t) => `<th>${t.replace(bracket + " ", "")}</th>`).join("")}</tr></thead>
        <tbody>${pool
          .map((row) => {
            const cells = pool
              .map((col) => {
                if (row === col) return `<td data-cell="self">—</td>`;
                const n = counts.get([row, col].sort().join("|")) || 0;
                return `<td data-pair="${row}|${col}" data-meetings="${n}">${n || "·"}</td>`;
              })
              .join("");
            return `<tr data-matrix-row="${row}"><th>${row.replace(bracket + " ", "")}</th>${cells}</tr>`;
          })
          .join("")}</tbody></table>
      </div>`;
    })
    .join("");
}

